package com.fasterxml.jackson.core.filter;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonLocation;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.util.JsonParserDelegate;
import java.io.*;
import java.io.IOException;
import java.io.OutputStream;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for FilteringParserDelegate#nextToken
 */
public class FilteringParserDelegate_nextToken_TriageGen1Test {

    private JsonParser mockDelegate;
    private TokenFilter mockFilter;
    private TokenFilterContext mockHeadContext;
    private TokenFilterContext mockChildContext;

    // Since FilteringParserDelegate is a class with protected/package-private fields,
    // and we need to test its logic, we create a testable subclass to inject mocks
    // if the constructor doesn't allow direct field manipulation.
    // However, based on the provided signature, we will use a subclass to expose internal state for testing.
    private static class TestableFilteringParserDelegate extends FilteringParserDelegate {
        public JsonToken _currToken;
        public TokenFilterContext _exposedContext;
        public TokenFilterContext _headContext;
        public TokenFilter _itemFilter;
        public boolean _includePath;
        public boolean _allowMultipleMatches;
        public boolean _includeImmediateParent;

        public TestableFilteringParserDelegate(JsonParser p, TokenFilter f, boolean includePath, boolean allowMultipleMatches) {
            super(p, f, includePath, allowMultipleMatches);
            this._headContext = null; // Will be set in tests
        }

        // Overriding to prevent actual delegation to protected methods if not implemented in mock
        @Override
        protected JsonToken _nextToken2() throws IOException {
            return null; 
        }

        @Override
        protected JsonToken _nextTokenWithBuffering(TokenFilterContext buffRoot) throws IOException {
            return null;
        }
    }

    private TestableFilteringParserDelegate delegate;

    @Before
    public void setUp() throws IOException {
        mockDelegate = mock(JsonParser.class);
        mockFilter = mock(TokenFilter.class);
        mockHeadContext = mock(TokenFilterContext.class);
        mockChildContext = mock(TokenFilterContext.class);

        // Default setup
        delegate = new TestableFilteringParserDelegate(mockDelegate, mockFilter, false, true);
        delegate._headContext = mockHeadContext;
    }

    @Test
    public void testNextToken_ScalarMultipleMatchFalse_ReturnsNull() throws IOException {
        delegate._allowMultipleMatches = false;
        delegate._currToken = mock(JsonToken.class);
        when(delegate._currToken.isScalarValue()).thenReturn(true);
        when(mockHeadContext.isStartHandled()).thenReturn(false);
        delegate._includePath = false;
        delegate._itemFilter = TokenFilter.INCLUDE_ALL;

        JsonToken result = delegate.nextToken();

        assertNull(result);
        assertNull(delegate._currToken);
    }

    @Test
    public void testNextToken_BufferedContext_ReturnsNextToken() throws IOException {
        delegate._exposedContext = mockChildContext;
        JsonToken expectedToken = JsonToken.VALUE_STRING;
        when(mockChildContext.nextTokenToRead()).thenReturn(expectedToken);

        JsonToken result = delegate.nextToken();

        assertEquals(expectedToken, result);
        assertEquals(expectedToken, delegate._currToken);
    }

    @Test
    public void testNextToken_BufferedContext_EndReachedInHeadContext() throws IOException {
        delegate._exposedContext = mockHeadContext;
        when(mockHeadContext.nextTokenToRead()).thenReturn(null);
        when(mockHeadContext.inArray()).thenReturn(true);
        when(mockDelegate.getCurrentToken()).thenReturn(JsonToken.END_ARRAY);

        JsonToken result = delegate.nextToken();

        assertEquals(JsonToken.END_ARRAY, result);
        assertNull(delegate._exposedContext);
    }

    @Test
    public void testNextToken_NoBufferedContext_ReadMore_EndArray() throws IOException {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.END_ARRAY);
        when(mockHeadContext.isStartHandled()).thenReturn(true);

        JsonToken result = delegate.nextToken();

        assertEquals(JsonToken.END_ARRAY, result);
    }

    @Test
    public void testNextToken_NoBufferedContext_ReadMore_EndObject() throws IOException {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.END_OBJECT);
        when(mockHeadContext.isStartHandled()).thenReturn(false);
        when(mockHeadContext.getFilter()).thenReturn(mockFilter);
        when(mockHeadContext.getParent()).thenReturn(mockHeadContext);

        JsonToken result = delegate.nextToken();

        assertEquals(JsonToken.END_OBJECT, result);
    }

    @Test
    public void testNextToken_StartArray_IncludeAll() throws IOException {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.START_ARRAY);
        delegate._itemFilter = TokenFilter.INCLUDE_ALL;
        when(mockHeadContext.createChildArrayContext(TokenFilter.INCLUDE_ALL, true)).thenReturn(mockChildContext);

        JsonToken result = delegate.nextToken();

        assertEquals(JsonToken.START_ARRAY, result);
        verify(mockHeadContext).createChildArrayContext(TokenFilter.INCLUDE_ALL, true);
    }

    @Test
    public void testNextToken_StartArray_FilterNull_Skips() throws IOException {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.START_ARRAY);
        delegate._itemFilter = null;

        JsonToken result = delegate.nextToken();

        assertNull(result);
        verify(mockDelegate).skipChildren();
    }

    @Test
    public void testNextToken_StartObject_IncludeAll() throws IOException {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.START_OBJECT);
        delegate._itemFilter = TokenFilter.INCLUDE_ALL;
        when(mockHeadContext.createChildObjectContext(TokenFilter.INCLUDE_ALL, true)).thenReturn(mockChildContext);

        JsonToken result = delegate.nextToken();

        assertEquals(JsonToken.START_OBJECT, result);
    }

    @Test
    public void testNextToken_FieldName_IncludeAll() throws IOException {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.FIELD_NAME);
        when(mockDelegate.getCurrentName()).thenReturn("testField");
        when(mockHeadContext.setFieldName("testField")).thenReturn(TokenFilter.INCLUDE_ALL);
        delegate._includePath = false;
        delegate._includeImmediateParent = true;
        when(mockHeadContext.isStartHandled()).thenReturn(false);
        when(mockHeadContext.nextTokenToRead()).thenReturn(JsonToken.START_OBJECT);

        JsonToken result = delegate.nextToken();

        assertEquals(JsonToken.START_OBJECT, result);
    }

    @Test
    public void testNextToken_FieldName_FilterNull_Skips() throws IOException {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.FIELD_NAME);
        when(mockDelegate.getCurrentName()).thenReturn("testField");
        when(mockHeadContext.setFieldName("testField")).thenReturn(null);

        JsonToken result = delegate.nextToken();

        assertNull(result);
        verify(mockDelegate).nextToken();
        verify(mockDelegate).skipChildren();
    }

    @Test
    public void testNextToken_Default_ScalarValue_IncludeAll() throws IOException {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.VALUE_NUMBER_INT);
        delegate._itemFilter = TokenFilter.INCLUDE_ALL;

        JsonToken result = delegate.nextToken();

        assertEquals(JsonToken.VALUE_NUMBER_INT, result);
    }

    @Test
    public void testNextToken_Default_ScalarValue_CheckValue() throws IOException {
        when(mockDelegate.nextToken()).thenReturn(JsonToken.VALUE_STRING);
        delegate._itemFilter = mockFilter;
        when(mockHeadContext.checkValue(mockFilter)).thenReturn(TokenFilter.INCLUDE_ALL);

        JsonToken result = delegate.nextToken();

        assertEquals(JsonToken.VALUE_STRING, result);
    }

    @Test
    public void testNextToken_DelegateReturnsNull() throws IOException {
        when(mockDelegate.nextToken()).thenReturn(null);

        JsonToken result = delegate.nextToken();

        assertNull(result);
        assertNull(delegate._currToken);
    }

    @Test(expected = IOException.class)
    public void testNextToken_BrokenContextChain_ThrowsException() throws IOException {
        delegate._exposedContext = mockChildContext;
        when(mockChildContext.nextTokenToRead()).thenReturn(null);
        when(mockHeadContext.findChildOf(mockChildContext)).thenReturn(null);

        delegate.nextToken();
    }
}
